namespace G.PcHealthCheck;

public sealed partial class MainForm
{
    private ExecutionContextInfo? _executionContext;
    private readonly Label _contextBanner = new() { Name = "ExecutionContextBanner", AutoSize = true, Dock = DockStyle.Fill, Padding = new Padding(8) };
    private readonly Button _contextDetails = new() { Text = AppLocalization.T("Main.ExecutionContext.Details"), AutoSize = true, Dock = DockStyle.Fill };

    private Control ExecutionContextPanel()
    {
        var panel = new TableLayoutPanel { Dock = DockStyle.Fill, AutoSize = true, ColumnCount = 2, RowCount = 1, Margin = new Padding(0, 0, 0, 8) };
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        panel.Controls.Add(_contextBanner, 0, 0); panel.Controls.Add(_contextDetails, 1, 0);
        _contextDetails.Click += (_, _) => { using var form = new ExecutionContextForm(_executionContext); form.ShowDialog(this); };
        RenderExecutionContext(null);
        return panel;
    }

    private void RenderExecutionContext(ExecutionContextInfo? context)
    {
        _executionContext = context;
        _contextBanner.Text = context is null
            ? AppLocalization.T("Main.ExecutionContext.NotCaptured")
            : AppLocalization.T(
                "Main.ExecutionContext.ProcessSession",
                ExecutionPolicy.ModeText(context),
                ExecutionPolicy.Value(context.ProcessAccount),
                context.SessionId,
                ExecutionPolicy.Value(context.SessionAccount));
        _contextBanner.ForeColor = context is null || !ExecutionPolicy.SameUser(context) ? Warn : Navy;
    }

    private ActionAvailability AvailabilityFor(ActionRecommendation action)
        => !action.CanAutomate
            ? new("Manual", AppLocalization.T("Main.ExecutionContext.ManualReason"), "—")
            : ExecutionPolicy.For(action.Id, _executionContext ?? new ExecutionContextInfo());

    private void RefreshActionAvailability()
    {
        foreach (DataGridViewRow row in _actions.Rows)
        {
            if (row.Tag is not ActionRecommendation action) continue;
            var availability = AvailabilityFor(action);
            row.Cells["Availability"].Value = ExecutionPolicy.StateText(availability.State);
            row.Cells["Availability"].ToolTipText = AppLocalization.T("Main.ExecutionContext.ScopeTooltip", availability.Reason, availability.Scope);
            row.Cells["Selected"].ReadOnly = !availability.CanRequest;
            if (!availability.CanRequest) row.Cells["Selected"].Value = false;
        }
        // ToolTipText and context may change while the displayed State value stays identical.
        if (_actionDetails is not null) RefreshSelectedDetails(_actions, _actionDetails);
        UpdateApplyState();
    }

    internal static void StampExecutionContext(DiagnosticData data, ExecutionContextInfo context)
    {
        data.System.ExecutionContext = context;
        // Never relabel a console user's WMI value as the current RDP session user.
        data.System.UserName = ExecutionPolicy.Value(context.SessionAccount);
        data.System.IsAdministrator = context.HasAdministratorToken == true;
    }

    private static string ActionExecutionText(RemediationActionResult action)
        => AppLocalization.T(
            "Main.ExecutionContext.ActionScope",
            action.Message,
            ExecutionPolicy.Value(action.TargetScope),
            ExecutionPolicy.Describe(action.ExecutionContext));
}

namespace G.PcHealthCheck;

public sealed partial class MainForm
{
    private TableLayoutPanel? _mainLocalizationRoot;
    private bool _mainLocalizationInitialized;
    private bool _refreshingMainLocalization;

    private void InitializeMainLocalization(TableLayoutPanel root)
    {
        if (_mainLocalizationInitialized) return;
        _mainLocalizationInitialized = true;
        _mainLocalizationRoot = root;
        InitializeSecurityPostureUi(root);
        AppLocalization.CultureChanged += OnMainCultureChanged;
        Disposed += (_, _) => AppLocalization.CultureChanged -= OnMainCultureChanged;

        // UpdateApplyState() runs once after BuildUi() and still owns the selected-count
        // semantics. This hook keeps its caption localized without using translated text
        // as program logic.
        _apply.TextChanged += (_, _) => LocalizeApplyButton();
        RefreshMainLocalization();
    }

    private void OnMainCultureChanged(object? sender, EventArgs e)
    {
        if (IsDisposed) return;
        if (IsHandleCreated && InvokeRequired)
        {
            BeginInvoke((Action)RefreshMainLocalization);
            return;
        }
        RefreshMainLocalization();
    }

    private void RefreshMainLocalization()
    {
        if (_refreshingMainLocalization || _mainLocalizationRoot is null) return;
        _refreshingMainLocalization = true;
        try
        {
            LocalizeHeader();
            LocalizeMetrics();
            LocalizeTabsAndColumns();
            RefreshSecurityLocalization();

            _scan.Text = AppLocalization.T("Main.Button.Rescan");
            _openReport.Text = AppLocalization.T("Main.Button.OpenReport");
            _openFolder.Text = AppLocalization.T("Main.Button.ReportsFolder");
            _copySummary.Text = AppLocalization.T("Main.Button.CopySummary");
            LocalizeApplyButton();

            _contextDetails.Text = AppLocalization.T("Main.ExecutionContext.Details");
            _selectAllAvailable.Text = AppLocalization.T("Main.ServiceDesk.SelectAll");
            _makeBetter.Text = AppLocalization.T("Main.ServiceDesk.MakeBetter");
            _doEverything.Text = AppLocalization.T("Main.ServiceDesk.DoEverything");
            RenderExecutionContext(_executionContext);
            RefreshActionAvailability();

            if (_current is { } scan)
            {
                _state.Text = scan.Assessment.Status switch
                {
                    "OK" => AppLocalization.T("Main.State.Ok"),
                    "WARN" => AppLocalization.T("Main.State.Warn"),
                    _ => AppLocalization.T("Main.State.Critical")
                };
                _uptime.Text = AppLocalization.T("Main.Uptime.Days", scan.Data.System.UptimeDays);
                var triage = TriageSummary.Build(scan);
                _tabs.TabPages["RecommendationsTab"]!.Text = triage.SignificantCount > 0
                    ? AppLocalization.T("Main.Tab.Recommendations.Count", triage.SignificantCount)
                    : AppLocalization.T("Main.Tab.Recommendations");
                RefreshRecommendationDisplayRows();
                RefreshSystemDisplayRows(scan);
            }

            if (!string.IsNullOrWhiteSpace(_status.Text))
                _status.Text = _isBusy ? AppLocalization.T("Main.Status.Working") : AppLocalization.T("Main.Status.ReadySimple");
        }
        finally
        {
            _refreshingMainLocalization = false;
        }
    }

    private void LocalizeHeader()
    {
        if (_mainLocalizationRoot?.GetControlFromPosition(0, 0) is not Control header) return;
        var subtitle = header.Controls.OfType<Label>()
            .Where(x => !ReferenceEquals(x, _host))
            .OrderBy(x => x.Font.Size)
            .FirstOrDefault();
        if (subtitle is not null) subtitle.Text = AppLocalization.T("Main.Header.Subtitle");
    }

    private void LocalizeMetrics()
    {
        if (_mainLocalizationRoot?.GetControlFromPosition(0, 2) is not TableLayoutPanel metrics) return;
        SetMetric(metrics, 0, "Main.Metric.Score", null);
        SetMetric(metrics, 1, "Main.Metric.Coverage", "Main.Metric.Coverage.Sub");
        SetMetric(metrics, 2, null, "Main.Metric.Cpu.Sub");
        SetMetric(metrics, 3, null, "Main.Metric.Ram.Sub");
        SetMetric(metrics, 4, "Main.Metric.SystemDisk", "Main.Metric.SystemDisk.Sub");
        SetMetric(metrics, 5, null, "Main.Metric.Uptime.Sub");
        SetMetric(metrics, 6, "Security.Metric.Caption", null);
    }

    private static IEnumerable<Control> DescendantsForLocalization(Control parent)
    {
        foreach (Control child in parent.Controls)
        {
            yield return child;
            foreach (var descendant in DescendantsForLocalization(child)) yield return descendant;
        }
    }

    private static void SetMetric(TableLayoutPanel metrics, int column, string? captionKey, string? subKey)
    {
        if (metrics.Controls.OfType<Panel>().ElementAtOrDefault(column) is not Panel card || card.Controls.Count < 3) return;
        if (captionKey is not null && card.Controls[0] is Label caption) caption.Text = AppLocalization.T(captionKey);
        if (subKey is not null) card.Controls[2].Text = AppLocalization.T(subKey);
    }

    private void LocalizeTabsAndColumns()
    {
        foreach (var (name, key) in new[] {
            ("OverviewTab", "Main.Tab.Overview"), ("RecommendationsTab", "Main.Tab.Recommendations"),
            ("ActionsTab", "Main.Tab.Actions"), ("ProcessesTab", "Main.Tab.Processes"),
            ("EventsTab", "Main.Tab.Events"), ("SystemTab", "Main.Tab.System"),
            ("CompareTab", "Main.Tab.Compare"), ("SecurityPostureTab", "Security.Tab.Title") })
            if (_tabs.TabPages[name] is TabPage page) page.Text = AppLocalization.T(key);
        foreach (var toggle in DescendantsForLocalization(this).OfType<Button>().Where(x => x.Name is "FindingDetailsToggle" or "ActionDetailsToggle"))
        {
            toggle.Text = AppLocalization.T("Main.Details.Toggle");
            toggle.AccessibleName = toggle.Text;
        }

        SetColumn(_actions, "Kind", "Main.Column.Type");
        SetColumn(_actions, "Title", "Main.Column.Action");
        SetColumn(_actions, "Reason", "Main.Column.Why");
        SetColumn(_actions, "Risk", "Main.Column.Risk");
        SetColumn(_actions, "Verify", "Main.Column.AutoVerify");
        SetColumn(_actions, "Availability", "Main.Column.Availability");

        SetColumn(_findings, "Severity", "Main.Column.Status");
        SetColumn(_findings, "Category", "Main.Column.Category");
        SetColumn(_findings, "Title", "Main.Column.Observation");
        SetColumn(_findings, "Value", "Main.Column.Value");
        SetColumn(_findings, "Recommendation", "Main.Column.Recommendation");

        SetColumn(_events, "Log", "Main.Column.Log");
        SetColumn(_events, "Count", "Main.Column.Count");
        SetColumn(_events, "Last", "Main.Column.Last");
        SetColumn(_system, "Property", "Main.Column.Parameter");
        SetColumn(_system, "Value", "Main.Column.Value");
        SetColumn(_compare, "Metric", "Main.Column.Metric");
        SetColumn(_compare, "Before", "Main.Column.Before");
        SetColumn(_compare, "After", "Main.Column.After");
        SetColumn(_compare, "Delta", "Main.Column.Change");
        SetColumn(_remediation, "Action", "Main.Column.Action");
        SetColumn(_remediation, "Result", "Main.Column.Result");
        SetColumn(_remediation, "Details", "Main.Column.DetailsContext");
        SetColumn(_topCpu, "Process", "Main.Column.Process");
        SetColumn(_topRam, "Process", "Main.Column.Process");
        SetColumn(_topIo, "Process", "Main.Column.Process");
    }

    private static void SetColumn(DataGridView grid, string name, string key)
    {
        if (grid.Columns.Contains(name)) grid.Columns[name].HeaderText = AppLocalization.T(key);
    }

    private void LocalizeApplyButton()
    {
        if (_refreshingMainLocalization && _apply.IsDisposed) return;
        var count = SelectedAutomatableActions().Count;
        var text = count > 0
            ? AppLocalization.T("Main.Button.ApplySelected.Count", count)
            : AppLocalization.T("Main.Button.ApplySelected");
        if (!string.Equals(_apply.Text, text, StringComparison.Ordinal)) _apply.Text = text;
    }

    private static string RecommendationClassText(RecommendationClass value) => value switch
    {
        RecommendationClass.Recommended => AppLocalization.T("Main.Recommendation.Recommended"),
        RecommendationClass.Optional => AppLocalization.T("Main.Recommendation.Optional"),
        _ => AppLocalization.T("Main.Recommendation.Manual")
    };

    private void RefreshRecommendationDisplayRows()
    {
        foreach (DataGridViewRow row in _actions.Rows)
        {
            if (row.Tag is not ActionRecommendation action) continue;
            row.Cells["Kind"].Value = RecommendationClassText(action.RecommendationClass);
            row.Cells["Admin"].Value = action.RequiresAdmin ? AppLocalization.T("Common.Yes") : AppLocalization.T("Common.No");
            var availability = AvailabilityFor(action);
            row.Cells["Availability"].Value = ExecutionPolicy.StateText(availability.State);
            row.Cells["Availability"].ToolTipText = AppLocalization.T("Main.ExecutionContext.ScopeTooltip", availability.Reason, availability.Scope);
        }
    }

    private void RefreshSystemDisplayRows(ScanResult scan)
    {
        var d = scan.Data;
        var labels = new[]
        {
            "Main.System.Computer", "Main.System.SessionUser", "Main.System.ManufacturerModel", null, null, null,
            "Main.System.WindowsVolume", "Main.System.LastBoot", "Main.System.ProcessRights", "Main.System.ProcessAccountSession",
            "Main.System.SessionProfile", "Main.System.ContextLimits", "Main.System.Coverage", "Main.System.MissingSignals",
            "Main.System.PendingReboot", null, "Main.System.Protection", "Main.System.PhysicalDisks", "Main.System.Startup", "Main.System.CollectionWarnings"
        };
        for (var i = 0; i < _system.Rows.Count && i < labels.Length; i++)
            if (labels[i] is { } key) _system.Rows[i].Cells[0].Value = AppLocalization.T(key);

        if (_system.Rows.Count > 6 && string.IsNullOrWhiteSpace(SystemDiskSelection.CurrentDriveId))
            _system.Rows[6].Cells[1].Value = AppLocalization.T("Common.NotDetermined");
        if (_system.Rows.Count > 9 && d.System.ExecutionContext is null)
            _system.Rows[9].Cells[1].Value = ExecutionPolicy.Value(d.System.ExecutionContext?.ProcessAccount) + " / " + AppLocalization.T("Main.System.ContextNotSaved");
        if (_system.Rows.Count > 11 && d.System.ExecutionContext is null)
            _system.Rows[11].Cells[1].Value = AppLocalization.T("Main.System.ContextNotSaved");
        if (_system.Rows.Count > 13 && scan.Assessment.MissingSignals.Count == 0)
            _system.Rows[13].Cells[1].Value = AppLocalization.T("Common.No");
        if (_system.Rows.Count > 14)
            _system.Rows[14].Cells[1].Value = d.PendingReboot.Pending
                ? AppLocalization.T("Common.Yes") + " — " + string.Join("; ", d.PendingReboot.Reasons)
                : AppLocalization.T("Common.No");
        if (_system.Rows.Count > 16 && d.SecurityProducts.Count == 0)
            _system.Rows[16].Cells[1].Value = AppLocalization.T("Common.CouldNotDetermine");
        if (_system.Rows.Count > 17 && d.PhysicalDisks.Count == 0)
            _system.Rows[17].Cells[1].Value = AppLocalization.T("Common.CouldNotDetermine");
        if (_system.Rows.Count > 18)
            _system.Rows[18].Cells[1].Value = AppLocalization.T("Main.System.StartupItems", d.StartupItems.Count);
    }
}

namespace G.PcHealthCheck;

public sealed partial class MainForm
{
    private void ArmReadableLayout(TableLayoutPanel root)
    {
        if (root.GetControlFromPosition(0, 2) is not TableLayoutPanel metrics) return;
        metrics.Name = "AdaptiveMetrics";
        bool busy = false;
        void Arrange()
        {
            if (busy || metrics.ClientSize.Width <= 0) return;
            busy = true;
            try
            {
                var cards = metrics.Controls.OfType<Panel>().ToArray();
                var geometry = ReadableLayout.Metrics(metrics.ClientSize.Width, DeviceDpi / 96f, cards.Length);
                metrics.SuspendLayout();
                metrics.ColumnCount = geometry.Columns; metrics.RowCount = geometry.Rows;
                metrics.ColumnStyles.Clear(); metrics.RowStyles.Clear();
                for (int i = 0; i < geometry.Columns; i++) metrics.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f / geometry.Columns));
                for (int i = 0; i < geometry.Rows; i++) metrics.RowStyles.Add(new RowStyle(SizeType.Percent, 100f / geometry.Rows));
                for (int i = 0; i < cards.Length; i++) metrics.SetCellPosition(cards[i], new TableLayoutPanelCellPosition(i % geometry.Columns, i / geometry.Columns));
                root.RowStyles[2].Height = geometry.Height;
                // Only the Overview scrolls; tabs and footer stay within the window.
                root.Height = (int)Math.Ceiling((86 + 76 + 16) * DeviceDpi / 96f)
                    + geometry.Height + root.GetControlFromPosition(0, 1)!.GetPreferredSize(new Size(metrics.Width, 0)).Height
                    + (int)Math.Ceiling(8 * DeviceDpi / 96f);
                metrics.ResumeLayout();
            }
            finally { busy = false; }
        }
        if (root.Parent is Panel viewport) viewport.ClientSizeChanged += (_, _) => Arrange();
        metrics.SizeChanged += (_, _) => Arrange();
        DpiChanged += (_, _) => ReadableWindowLayout.AfterScaling(this, Arrange);
        Arrange();
    }

    private static void ArmProportionalSplit(SplitContainer split, double initialRatio, int upperMin, int lowerMin)
    {
        double ratio = initialRatio; bool arranging = false;
        split.SplitterMoved += (_, _) => { if (!arranging && split.Height > split.SplitterWidth) ratio = (double)split.SplitterDistance / (split.Height - split.SplitterWidth); };
        split.SizeChanged += (_, _) =>
        {
            int available = split.ClientSize.Height - split.SplitterWidth;
            float scale = split.DeviceDpi / 96f;
            if (available <= 0) return;
            arranging = true;
            try
            {
                // Set minimums only when the actual pane can accommodate both.
                split.Panel1MinSize = 0; split.Panel2MinSize = 0;
                int upper = (int)Math.Ceiling(upperMin * scale), lower = (int)Math.Ceiling(lowerMin * scale);
                if (available >= upper + lower)
                {
                    split.SplitterDistance = upperMin == 90 && lowerMin == 80
                        ? ReadableLayout.Split(available, scale, ratio)
                        : Math.Clamp((int)(available * ratio), upper, available - lower);
                    split.Panel1MinSize = upper; split.Panel2MinSize = lower;
                }
                else split.SplitterDistance = available / 2;
            }
            finally { arranging = false; }
        };
    }

    private TextBox? _actionDetails;

    private static void RefreshSelectedDetails(DataGridView grid, TextBox detail)
    {
        var row = grid.CurrentRow;
        detail.Text = row is null || !row.Selected ? "" : string.Join(Environment.NewLine + Environment.NewLine,
            grid.Columns.Cast<DataGridViewColumn>().Select(c => c.HeaderText + ": " + Convert.ToString(row.Cells[c.Index].Value)
                + (c.Name == "Availability" && !string.IsNullOrWhiteSpace(row.Cells[c.Index].ToolTipText)
                    ? Environment.NewLine + row.Cells[c.Index].ToolTipText : "")));
    }

    private Control DetailPane(DataGridView grid, string name)
    {
        var wrapper = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 1, RowCount = 2 };
        wrapper.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        wrapper.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        wrapper.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        var toggle = new Button { Name = name + "Toggle", Text = AppLocalization.T("Main.Details.Toggle"), AutoSize = true, Anchor = AnchorStyles.Left, AccessibleName = AppLocalization.T("Main.Details.Toggle") };
        var split = new SplitContainer { Dock = DockStyle.Fill, Orientation = Orientation.Horizontal, Name = name + "Pane", Panel2Collapsed = true };
        ArmProportionalSplit(split, .70, 40, 35);
        var detail = new TextBox { Name = name, Dock = DockStyle.Fill, ReadOnly = true, Multiline = true, ScrollBars = ScrollBars.Both, WordWrap = false, BackColor = SystemColors.Window, AccessibleName = name };
        if (ReferenceEquals(grid, _actions)) _actionDetails = detail;
        void Refresh() => RefreshSelectedDetails(grid, detail);
        grid.CurrentCellChanged += (_, _) => Refresh();
        // SelectionChanged precedes CurrentCellChanged; never read old CurrentRow here.
        grid.SelectionChanged += (_, _) =>
        {
            if (grid.SelectedRows.Count == 0) detail.Clear();
            else if (grid.FindForm() is Form form)
                ReadableWindowLayout.AfterScaling(form, Refresh); // after CurrentCell update, also same-cell reselection
        };
        grid.CellValueChanged += (_, _) => Refresh();
        grid.RowsAdded += (_, _) => Refresh();
        split.Panel1.Controls.Add(grid); split.Panel2.Controls.Add(detail);
        toggle.Click += (_, _) => { split.Panel2Collapsed = !split.Panel2Collapsed; if (!split.Panel2Collapsed) Refresh(); };
        grid.CellDoubleClick += (_, e) => { if (e.RowIndex >= 0) { split.Panel2Collapsed = false; Refresh(); } };
        wrapper.Controls.Add(toggle, 0, 0); wrapper.Controls.Add(split, 0, 1);
        return wrapper;
    }
}

namespace G.PcHealthCheck;

public sealed partial class MainForm
{
    private readonly CheckBox _selectAllAvailable = new()
    {
        Name = "SelectAllAvailable",
        Text = AppLocalization.T("Main.ServiceDesk.SelectAll"),
        AutoSize = true,
        Padding = new Padding(0, 7, 8, 0)
    };
    private readonly Button _makeBetter = BatchButton("MakeBetter", AppLocalization.T("Main.ServiceDesk.MakeBetter"), Color.FromArgb(23, 122, 75));
    private readonly Button _doEverything = BatchButton("DoEverything", AppLocalization.T("Main.ServiceDesk.DoEverything"), Color.FromArgb(181, 54, 54));
    private bool _serviceDeskActionsUiInitialized;
    private bool _syncingSelectAll;

    protected override void OnLoad(EventArgs e)
    {
        EnsureServiceDeskActionsUi();
        base.OnLoad(e);
    }

    private void EnsureServiceDeskActionsUi()
    {
        if (_serviceDeskActionsUiInitialized) return;
        _serviceDeskActionsUiInitialized = true;

        var page = _tabs.TabPages["ActionsTab"];
        var layout = page?.Controls.OfType<TableLayoutPanel>().FirstOrDefault();
        if (layout is null)
            throw new InvalidOperationException(AppLocalization.T("Main.ServiceDesk.MissingPanel"));

        var bar = new FlowLayoutPanel
        {
            Name = "ServiceDeskActionBar",
            Dock = DockStyle.Fill,
            AutoSize = true,
            WrapContents = true,
            FlowDirection = FlowDirection.LeftToRight,
            Padding = new Padding(4, 3, 4, 2),
            Margin = new Padding(0, 0, 0, 4)
        };
        _hardenSecurity.AutoSize = true;
        _makeBetter.AutoSize = true;
        _doEverything.AutoSize = true;
        _doEverything.Enabled = ServiceDeskActionRegistry.ExecutableHandlerIds.Count == ServiceDeskActionRegistry.All.Count;
        _doEverything.Cursor = _doEverything.Enabled ? Cursors.Hand : Cursors.Default;
        bar.Controls.AddRange([_selectAllAvailable, _hardenSecurity, _makeBetter, _doEverything]);
        layout.Controls.Add(bar, 0, 0);

        _selectAllAvailable.CheckedChanged += (_, _) => ApplySelectAllAvailable();
        _actions.CellValueChanged += (_, e) =>
        {
            if (e.RowIndex >= 0 && e.ColumnIndex == _actions.Columns["Selected"].Index && !_syncingSelectAll)
                SyncSelectAllAvailable();
        };
        _actions.RowsAdded += (_, _) => SyncSelectAllAvailable();
        _actions.RowsRemoved += (_, _) => SyncSelectAllAvailable();
        _hardenSecurity.Click += async (_, _) => await HardenSecurityAsync();
        _makeBetter.Click += async (_, _) => await MakeBetterAsync();
        SyncSelectAllAvailable();
        RefreshSecurityHardeningButtonState();
        RefreshMainLocalization();
    }

    private async Task MakeBetterAsync()
    {
        if (_isBusy || _current is null) return;
        BatchPreflight preflight;
        try
        {
            Busy(true, AppLocalization.T("Main.ServiceDesk.CheckRecommended"));
            var context = await Task.Run(ExecutionContextService.Capture);
            RenderExecutionContext(context);
            preflight = ServiceDeskBatchPlanner.Plan(
                BatchMode.RecommendedBestEffort,
                _current.Actions,
                Array.Empty<string>(),
                id => ExecutionPolicy.For(id, context));

            var runnable = preflight.Actions
                .Where(x => x.State == PlannedActionState.Run && ServiceDeskActionRegistry.IsExecutableHandler(x.Descriptor.Id))
                .Select(x => x.Descriptor.Id)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            SelectOnlyActionRows(runnable);
            if (runnable.Count == 0)
            {
                var skipped = preflight.Actions.Where(x => x.State == PlannedActionState.Skipped).ToList();
                var detail = skipped.Count == 0
                    ? AppLocalization.T("Main.ServiceDesk.NoRecommended")
                    : AppLocalization.T(
                        "Main.ServiceDesk.RecommendedUnavailable",
                        string.Join("\n", skipped.Select(x => x.Descriptor.Id + ": " + x.Reason)));
                MessageBox.Show(this, detail, AppLocalization.T("Main.ServiceDesk.MakeBetter"), MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, AppLocalization.T("Main.ServiceDesk.PrepareFailed"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }
        finally
        {
            Busy(false);
            RefreshSecurityHardeningButtonState();
        }

        await ApplyAsync();
    }

    private void ApplySelectAllAvailable()
    {
        if (_syncingSelectAll) return;
        _syncingSelectAll = true;
        try
        {
            foreach (var row in RequestableAutomatedRows())
                row.Cells["Selected"].Value = _selectAllAvailable.Checked;
        }
        finally
        {
            _syncingSelectAll = false;
        }
        UpdateApplyState();
    }

    private void SelectOnlyActionRows(IReadOnlySet<string> ids)
    {
        _syncingSelectAll = true;
        try
        {
            foreach (DataGridViewRow row in _actions.Rows)
            {
                if (row.Tag is not ActionRecommendation action || !action.CanAutomate || row.Cells["Selected"].ReadOnly) continue;
                row.Cells["Selected"].Value = ids.Contains(action.Id);
            }
        }
        finally
        {
            _syncingSelectAll = false;
        }
        SyncSelectAllAvailable();
        UpdateApplyState();
    }

    private List<DataGridViewRow> RequestableAutomatedRows()
        => _actions.Rows.Cast<DataGridViewRow>()
            .Where(row => row.Tag is ActionRecommendation action
                && action.CanAutomate
                && action.RecommendationClass != RecommendationClass.Manual
                && !row.Cells["Selected"].ReadOnly)
            .ToList();

    private void SyncSelectAllAvailable()
    {
        if (_syncingSelectAll || !_serviceDeskActionsUiInitialized) return;
        var rows = RequestableAutomatedRows();
        var shouldCheck = rows.Count > 0 && rows.All(row => Convert.ToBoolean(row.Cells["Selected"].Value ?? false));
        if (_selectAllAvailable.Checked == shouldCheck) return;
        _syncingSelectAll = true;
        try { _selectAllAvailable.Checked = shouldCheck; }
        finally { _syncingSelectAll = false; }
    }

    private static Button BatchButton(string name, string text, Color background)
        => new()
        {
            Name = name,
            Text = text,
            BackColor = background,
            ForeColor = Color.White,
            FlatStyle = FlatStyle.Flat,
            UseVisualStyleBackColor = false,
            AutoSize = true,
            Padding = new Padding(10, 3, 10, 3),
            Margin = new Padding(4, 0, 0, 0),
