    private void ApplyScanProgress(object owner, string text)
    {
        if (!IsDisposed && ReferenceEquals(_scanProgressOwner, owner)) _status.Text = text;
    }

    private void ApplyOperationProgress(object owner, string text)
    {
        if (!IsDisposed && ReferenceEquals(_applyProgressOwner, owner)) _status.Text = text;
    }

    private async Task ScanAsync()
    {
        if (_isBusy) return;
        var started = Stopwatch.StartNew();
        var progressOwner = new object();
        _scanProgressOwner = progressOwner;
        try
        {
            Busy(true, "Определяю контекст диагностики…");
            var context = await Task.Run(ExecutionContextService.Capture);
            RenderExecutionContext(context);
            var progress = new Progress<string>(s => ApplyScanProgress(progressOwner, s));
            var data = await _diagnostics.CollectAsync(progress);
            StampExecutionContext(data, context);
            var scan = _assessment.Assess(data);
            await AttachSecurityPostureAsync(scan, progress);
            _current = scan;
            var saved = _reports.SaveScan(_current);
            _latestReport = saved.Html;
            Populate(_current);
            _scanProgressOwner = null;
            _status.Text = $"Готово · {DateTime.Now:HH:mm:ss} · {started.Elapsed.TotalSeconds:0.0} с";
        }
        catch (Exception ex) { MessageBox.Show(this, ex.Message, "Ошибка диагностики", MessageBoxButtons.OK, MessageBoxIcon.Error); }
        finally
        {
            if (ReferenceEquals(_scanProgressOwner, progressOwner)) _scanProgressOwner = null;
            Busy(false);
        }
    }

    private async Task ApplyAsync()
    {
        if (_isBusy || _current is null) return;
        _actions.EndEdit();
        var selected = SelectedAutomatableActions();
        if (selected.Count == 0)
        {
            UpdateApplyState();
            return;
        }
        try
        {
            Busy(true, "Проверяю права и область выбранных действий…");
            var context = await Task.Run(ExecutionContextService.Capture);
            RenderExecutionContext(context);
            RefreshActionAvailability();
            var blocked = selected.Select(x => (Action: x, Availability: ExecutionPolicy.For(x.Id, context)))
                .Where(x => !x.Availability.CanRequest).ToList();
            if (blocked.Count > 0)
            {
                MessageBox.Show(this, "Набор не выполнен. Доступность изменилась или контекст не подтверждён:\n\n"
                    + string.Join("\n", blocked.Select(x => x.Action.Title + ": " + x.Availability.Reason)), "Проверьте выбранные действия", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }
        }
        catch (Exception ex) { MessageBox.Show(this, ex.Message, "Не удалось проверить контекст", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; }
        finally { Busy(false); }

        var summary = string.Join(Environment.NewLine, selected.Select(a => "• " + a.Title + " — "
            + ExecutionPolicy.StateText(AvailabilityFor(a).State) + "\n  Область: " + AvailabilityFor(a).Scope));
        if (MessageBox.Show(this, "Будут выполнены выбранные действия:\n\n" + summary + "\n\nПосле выполнения программа автоматически повторит диагностику в исходном процессе.", "Подтвердите действия", MessageBoxButtons.OKCancel, MessageBoxIcon.Warning) != DialogResult.OK) return;

        var before = _current;
        object? activeProgressOwner = null;
        try
        {
            Busy(true, "Выполняю выбранные действия…");
            var remediationOwner = new object();
            activeProgressOwner = remediationOwner;
            _applyProgressOwner = remediationOwner;
            var remediationProgress = new Progress<string>(s => ApplyOperationProgress(remediationOwner, s));
            var batch = await RemediationWorker.ExecuteFromGuiAsync(selected, _assessment.Thresholds.TempOlderThanDays, remediationProgress);

            var verificationOwner = new object();
            activeProgressOwner = verificationOwner;
            _applyProgressOwner = verificationOwner;
            _status.Text = "Повторная диагностика после remediation…";
            var verificationProgress = new Progress<string>(s => ApplyOperationProgress(verificationOwner, s));
            var context = await Task.Run(ExecutionContextService.Capture);
            var afterData = await _diagnostics.CollectAsync(verificationProgress);
            StampExecutionContext(afterData, context);
            var after = _assessment.Assess(afterData);
            await AttachSecurityPostureAsync(after, verificationProgress);
            if (ReferenceEquals(_applyProgressOwner, verificationOwner)) _applyProgressOwner = null;
            var verification = new VerificationResult { Before = before, After = after, Remediation = batch };
            var saved = _reports.SaveVerification(verification);
            _latestReport = saved.Html;
            _current = after;
            Populate(after);
            PopulateVerification(verification);
            _tabs.SelectedIndex = 4;
            var ok = batch.Actions.Count(x => x.Success);
            MessageBox.Show(this, $"Выполнено: {ok}/{batch.Actions.Count}. Повторная диагностика завершена.\nИндекс: {before.Assessment.Score} → {after.Assessment.Score}.\nУстранение симптома нужно подтвердить отдельно.", "G PC Health", MessageBoxButtons.OK, batch.Actions.All(x => x.Success) ? MessageBoxIcon.Information : MessageBoxIcon.Warning);
        }
        catch (OperationCanceledException ex)
        {
            _applyProgressOwner = null;
            MessageBox.Show(this, ex.Message, "Операция отменена", MessageBoxButtons.OK, MessageBoxIcon.Information);
        }
        catch (Exception ex)
        {
            _applyProgressOwner = null;
            MessageBox.Show(this, ex.Message, "Ошибка remediation", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        finally
        {
            if (activeProgressOwner is not null && ReferenceEquals(_applyProgressOwner, activeProgressOwner)) _applyProgressOwner = null;
            Busy(false);
        }
    }

    private List<ActionRecommendation> SelectedAutomatableActions()
    {
        var selected = new List<ActionRecommendation>();
        foreach (DataGridViewRow row in _actions.Rows)
        {
            if (row.Tag is not ActionRecommendation action || !action.CanAutomate || row.Cells["Selected"].ReadOnly) continue;
            if (Convert.ToBoolean(row.Cells["Selected"].Value ?? false)) selected.Add(action);
        }
        return selected;
    }

    private void UpdateApplyState()
    {
        var count = SelectedAutomatableActions().Count;
        _apply.Text = count > 0 ? $"Применить выбранное ({count})" : "Применить выбранное";
        _apply.Enabled = !_isBusy && count > 0;
        _apply.Cursor = _apply.Enabled ? Cursors.Hand : Cursors.Default;
    }

    private void Populate(ScanResult scan)
    {
        var d = scan.Data;
        RenderExecutionContext(d.System.ExecutionContext);
        _score.Text = scan.Assessment.Score.ToString(); _score.ForeColor = scan.Assessment.Status == "OK" ? Ok : scan.Assessment.Status == "WARN" ? Warn : Crit;
        _state.Text = scan.Assessment.Status == "OK" ? "норма" : scan.Assessment.Status == "WARN" ? "внимание" : "критично"; _state.ForeColor = _score.ForeColor;
        _host.Text = $"{d.System.ComputerName} · {d.System.UserName}";
        _cpu.Text = F(d.Performance.CpuPercent, "%"); _ram.Text = F(d.Performance.MemoryUsedPercent, "%");
        _ram.ForeColor = ReadableLayout.MemoryBand(d.Performance.MemoryAvailablePercent,
            _assessment.Thresholds.MemoryCriticalAvailablePercent, _assessment.Thresholds.MemoryWarnAvailablePercent) switch
        { "CRIT" => Crit, "WARN" => Warn, "UNKNOWN" => Muted, _ => Navy };
        var sd = SystemDiskSelection.Find(d); _disk.Text = sd is null ? "—" : $"{sd.FreeGB:0.#} GB";
        _uptime.Text = $"{d.System.UptimeDays:0.#} дн.";
        _coverage.Text = $"{scan.Assessment.CoveragePercent}%";
        _coverage.ForeColor = scan.Assessment.CoverageStatus == "HIGH" ? Ok : scan.Assessment.CoverageStatus == "MEDIUM" ? Warn : Crit;
        var triage = TriageSummary.Build(scan);
        _triageTitle.Text = triage.Title;
        _triageTitle.ForeColor = scan.Assessment.Status == "OK" ? Ok : scan.Assessment.Status == "WARN" ? Warn : Crit;
        _triageDetail.Text = triage.Detail;
        _tabs.TabPages["RecommendationsTab"]!.Text = triage.SignificantCount > 0 ? $"Рекомендации ({triage.SignificantCount})" : "Рекомендации";

        _actions.Rows.Clear();
        foreach (var a in scan.Actions)
        {
            var availability = AvailabilityFor(a);
            var i = _actions.Rows.Add(a.Preselected && availability.CanRequest, a.Kind, a.Title, a.Reason, a.RequiresAdmin ? "Да" : "Нет", a.Risk, a.Verification, ExecutionPolicy.StateText(availability.State));
            var row = _actions.Rows[i]; row.Tag = a;
            row.Cells["Availability"].ToolTipText = availability.Reason + "\nОбласть: " + availability.Scope;
            if (!availability.CanRequest)
            {
                row.Cells[0].ReadOnly = true;
                row.Cells[0].Style.BackColor = Color.FromArgb(240, 243, 246);
                row.Cells[0].Value = false;
                row.DefaultCellStyle.ForeColor = Color.FromArgb(85, 98, 110);
            }
            else if (a.Kind == "Рекомендуется")
            {
                row.DefaultCellStyle.BackColor = Color.FromArgb(240, 249, 244);
            }
        }
        UpdateApplyState();

        _findings.Rows.Clear();
        foreach (var f in scan.Assessment.Findings.OrderBy(x => x.Severity == "CRIT" ? 0 : x.Severity == "WARN" ? 1 : 2))
        {
            var i = _findings.Rows.Add(f.Severity, f.Category, f.Title, f.Value, f.Recommendation);
            var row = _findings.Rows[i];
            row.Cells[0].Style.ForeColor = f.Severity == "CRIT" ? Crit : f.Severity == "WARN" ? Warn : Ok;
            row.Cells[0].Style.Font = new Font(Font, FontStyle.Bold);
            if (f.Severity == "CRIT") row.DefaultCellStyle.BackColor = Color.FromArgb(255, 242, 242);
            else if (f.Severity == "WARN") row.DefaultCellStyle.BackColor = Color.FromArgb(255, 249, 235);
        }

        FillProcesses(_topCpu, d.TopCpu); FillProcesses(_topRam, d.TopMemory); FillProcesses(_topIo, d.TopIo);
        _events.Rows.Clear();
        foreach (var e in d.Events.Top) _events.Rows.Add(e.Log, e.Provider, e.EventId, e.Count, e.LastSeen);
        PopulateSystem(scan);
    }

    private void PopulateSystem(ScanResult scan)
    {
        var d = scan.Data;
        _system.Rows.Clear(); void Add(string k, string v) => _system.Rows.Add(k, v);
        Add("Компьютер", d.System.ComputerName); Add("Пользователь сеанса", d.System.UserName); Add("Производитель / модель", (d.System.Manufacturer + " " + d.System.Model).Trim());
        Add("Windows", $"{d.System.OS} {d.System.OSVersion} build {d.System.BuildNumber}"); Add("CPU", d.System.Cpu); Add("RAM", $"{d.System.TotalMemoryGB:0.#} GB");
        Add("Системный том Windows", SystemDiskSelection.CurrentDriveId ?? "Не определён");
        Add("Последняя загрузка", d.System.LastBoot.ToString("dd.MM.yyyy HH:mm:ss")); Add("Права процесса", ExecutionPolicy.ModeText(d.System.ExecutionContext));
        Add("Аккаунт процесса / сеанс", ExecutionPolicy.Value(d.System.ExecutionContext?.ProcessAccount) + " / " + (d.System.ExecutionContext?.SessionId.ToString() ?? "не сохранён"));
        Add("Профиль пользователя сеанса", ExecutionPolicy.Value(d.System.ExecutionContext?.SessionProfile));
        Add("Контекст: ограничения", d.System.ExecutionContext is null ? "Контекст не сохранён" : string.Join(" | ", d.System.ExecutionContext.Warnings));
        Add("Покрытие диагностики", $"{scan.Assessment.CoveragePercent}% ({scan.Assessment.CoverageStatus})");
        Add("Недоступные сигналы", scan.Assessment.MissingSignals.Count == 0 ? "Нет" : string.Join("; ", scan.Assessment.MissingSignals));
