        Add("Автозагрузка", d.StartupItems.Count + " элементов"); if (d.CollectionWarnings.Count > 0) Add("Предупреждения сбора", string.Join(" | ", d.CollectionWarnings));
    }

    private void PopulateVerification(VerificationResult v)
