        p.Paint += (_, e) => { var r = p.ClientRectangle; r.Width--; r.Height--; using var path = Rounded(r, 12); using var pen = new Pen(Line); e.Graphics.SmoothingMode = SmoothingMode.AntiAlias; e.Graphics.DrawPath(pen, path); };
